from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v != 0)
    color = min(counts, key=counts.get)
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0, c0 = min(r for r, c in cells), min(c for r, c in cells)
    shape = {(r-r0, c-c0) for r, c in cells}
    sh, sw = max(r for r, c in shape)+1, max(c for r, c in shape)+1
    out = [row[:] for row in grid]
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if all(grid[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = color
    return out

